@before(PreProcessRequest(maxdev))
class connected:
    """Retrieves or sets the connected state of the device."""
    def on_get(self, req: Request, resp: Response, devnum: int):
        try:
            is_conn = device.connected
            resp.text = PropertyResponse(is_conn, req).json
        except Exception as ex:
            resp.text = MethodResponse(req, DriverException(0x500, 'Focuser.Connected failed', ex)).json

    def on_put(self, req: Request, resp: Response, devnum: int):
        conn_str = get_request_field('Connected', req)
        conn = to_bool(conn_str)              # Raises 400 Bad Request if str to bool fails

        try:
            if conn:
                device.connect()
            else:
                device.disconnect()
            resp.text = MethodResponse(req).json
        except Exception as ex:
            resp.text = MethodResponse(req,
                            DriverException(0x500, 'Focuser.Connected failed', ex)).json

