@before(PreProcessRequest(maxdev))
class devicestate:
    """List of StateValue objects representing the operational properties of this device."""
    def on_get(self, req: Request, resp: Response, devnum: int):
        if not device.connected:
            resp.text = PropertyResponse(None, req,
                            NotConnectedException()).json
            return
        try:
            val = []
            val.append(StateValue('IsMoving', device.is_moving))
            val.append(StateValue('Position', device.position))
            val.append(StateValue('Temperature', device.temperature if device.temp_comp_available else None))
            resp.text = PropertyResponse(val, req).json
        except Exception as ex:
            resp.text = PropertyResponse(None, req,
                            DriverException(0x500, 'Focuser.Devicestate failed', ex)).json

