@before(PreProcessRequest(maxdev))
class move:
    """Move focuser to absolute position."""
    def on_put(self, req: Request, resp: Response, devnum: int):
        if not device.connected:
            resp.text = PropertyResponse(None, req,
                            NotConnectedException()).json
            return

        positionstr = get_request_field('Position', req)      # Raises 400 bad request if missing
        try:
            position = int(positionstr)
        except:
            resp.text = MethodResponse(req,
                            InvalidValueException(f'Position {positionstr} not a valid integer.')).json
            return

        try:
            device.move(position)
            resp.text = MethodResponse(req).json
        except Exception as ex:
            resp.text = MethodResponse(req,
                            DriverException(0x500, 'Focuser.Move failed', ex)).json

# ============================================================================
# INITIALIZATION
# ============================================================================

def start_foc_device(config, _logger, shared_onstepx=None):
    """Initialize focuser device with shared OnStepX connection.

    Args:
        config: Configuration object
        _logger: Logger instance
        shared_onstepx: Shared OnStepXDevice instance (created by app.py)
    """
    global logger, device, onstepx
    logger = _logger

    # Use shared OnStepX connection if provided
    if shared_onstepx is not None:
        onstepx = shared_onstepx
    else:
        # Create new instance (backward compatibility)
        onstepx = OnStepXDevice(
            logger=logger,
            port=config.serial_port,
            baud=config.baud_rate,
            timeout=config.timeout,
            connection_type=config.connection_type,
            tcp_host=getattr(config, 'tcp_host', None),
            tcp_port=getattr(config, 'tcp_port', None)
        )

    # Initialize focuser device
    focuser_num = getattr(config, 'focuser_number', 1)
    device = FocuserDevice(logger, onstepx, focuser_num)
    logger.info(f'OnStepX Focuser {focuser_num} device initialized')
